Let $\mathcal{F}=[f_{i_1,\ldots,i_d}],\mathcal{G}=[g_{i_1,\ldots,i_d}]\in\mathbb{R}_{pr,+}^{n^{\times d}}$.  Then
 \begin{equation}
 \rho(\mathcal{F}^{\circ \alpha}\circ\mathcal{G}^{\circ\beta})\leqslant (\rho(\mathcal{F}))^\alpha (\rho(\mathcal{G}))^\beta,\qquad  \alpha,\beta> 0, \alpha+\beta=1.
 \end{equation}
 Assume that $\mathcal{F}^{\circ \alpha}\circ\mathcal{G}^{\circ\beta}$ is weakly irreducible.  Let  $\mathbf{u}=(u_1,\ldots,u_n)^\top$ and $\mathbf{v}=(v_1,\ldots,v_n)^\top$ be the positive eigenvectors of $\mathcal{F}$ and $\mathcal{G}$: $\mathcal{F}(\mathbf{u})=\rho(T)\mathbf{u}^{\circ(d-1) }, \mathcal{G}(\mathbf{v})=\rho(\mathcal{G})\mathbf{v}^{\circ(d-1)}$.  Then  equality in the above inequality holds if and only if the following conditions are satisfied. There exists $\mathbf{a}=(a_1,\ldots,a_n)^\top >0$ such that
 \begin{equation}
 f_{i_1,\ldots,i_d}u_{i_2}\cdots u_{i_d}=a_{i_1}g_{i_1,\ldots,i_d}v_{i_2}\cdots v_{i_d} \quad \textrm{for all } i_1,\ldots,i_d\in[n].
 \end{equation}

Assume that $\mathcal{T}\in \mathbb{R}_{ps,+}^{n^{\times d}}$ is a weakly irreducible tensor.
 Let $A,\mathbf{u},\mathbf{w}$ be given by (3.17) and (3.18).  Assume that
 $\mathbf{y}=(y_1,\ldots,y_n)^\top>0$.  Then
 \begin{equation}
 \rho(\mathop{{\rm diag}}\nolimits(\mathbf{y})\circ \mathcal{T})\geqslant \rho(\mathcal{T})\prod_{i=1}^n y_i^{u_iw_i}.
 \end{equation}

Assume furthermore that $\mathcal{T}$ is a symmetric tensor and {{$\sum_{i=1}^n u_i^d=1$}}. Then
 \begin{equation}
 \rho(\mathop{{\rm diag}}\nolimits(\mathbf{y})\circ \mathcal{T})\geqslant \rho(\mathcal{T})\prod_{i=1}^n y_i^{u_i^d}.
 \end{equation}

The spectral radius of $\mathcal{T}=[t_{i_1,\ldots,i_d}]\in \mathbb{R}_{ps.+}^{n^{\times d}}$ has the following characterization 
\begin{eqnarray}
\log \rho(\mathcal{T}) &= 
\displaystyle 
\max_{\mu\in \Omega(n^{\times(d-1)})}
\sum_{i_1,\dots,i_d\in [n]}
\mu_{i_1,\dots, i_d} \log \Big(\frac{(\sum_{k_2,\dots, k_d}\mu_{i_1,k_2,\dots, k_d})t_{i_1,\dots, i_d}}{\mu_{i_1,\dots, i_d}}\Big) \enspace .

\end{eqnarray}
Assume that $\mathcal{T}$ is weakly irreducible. Let $\mathbf{u}>0$ be the unique positive eigenvector $\mathbf{u}$ satisfying (3.11) and let $\mathbf{w}>\mathbf{0}$ be defined as in (3.18).  Let $\mu=[\mu_{i_1,\ldots,i_d}]\in \mathbb{R}_{ps,+}^{n^{\times d}}$ be the tensor given by
\begin{equation}
\mu_{i_1,\ldots,i_d}=\frac{1}{\rho(\mathcal{T})} w_{i_1}u_{i_1}^{-(d-2)}t_{i_1,\ldots,i_d}u_{i_2}\cdots u_{i_d} \textrm{ for } i_1,\ldots,i_d\in[n].
\end{equation}
Then $\mu$ is an occupation measure whose support is $\operatorname{supp}{\mathcal}{T}$. Furthermore,
\begin{equation}
\log\rho(\mathcal{T})=\sum_{i_1,\ldots,i_d\in [n]} \mu_{i_1,\dots, i_d} \log \Big(\frac{(\sum_{k_2,\dots, k_d}\mu_{i_1,k_2\dots ,k_d})t_{i_1,\dots, i_d}}{\mu_{i_1,\dots ,i_d}}\Big) \enspace .
\end{equation}

Let $\mathcal{E}\in \mathbb{R}_{ps,+}^{n^{\times d}}$.  Then the following inequalities hold.
\begin{equation}
\rho_{\mathrm{trop}}(\mathcal{E}) \leqslant \rho(\mathcal{E}) \leqslant n^{d-1} \rho_{\mathrm{trop}}(\mathcal{E}) \enspace .

\end{equation}
